  "inlineSchema": "// ============================================================\n// SEAORA — La Perle\n// PostgreSQL schema.\n//\n// The original SQLite database kept four parallel tables — images, audios,\n// videos, notes — each with its own position column, and the viewer merged\n// them into a single pile at read time. Here they are one `Memory` table\n// discriminated by `type`, which is the same data with one ordering, one set\n// of CRUD endpoints and one place to add a fifth kind of memory later.\n// The four piles are still four piles: they are `type` filters ordered by\n// `position`, exactly as the experience expects.\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n/// A pearl is one gift: the sealed door, the letter, and its memories.\nmodel Pearl {\n  id     Int         @id @default(autoincrement())\n  slug   String      @unique\n  status PearlStatus @default(SEALED)\n\n  /// The one credential that opens the gift. scrypt, never in clear.\n  passHash String  @map(\"pass_hash\")\n  passSalt String  @map(\"pass_salt\")\n  /// An optional word shown on the gate when the visitor is stuck.\n  passHint String? @map(\"pass_hint\")\n\n  /// Optional SECOND secret — the reference engraved on the object. When it\n  /// is set, the gate asks for it in addition to the code. Hashed like the\n  /// code: the value never leaves the database, only the `needsRef` boolean.\n  refHash String? @map(\"ref_hash\")\n  refSalt String? @map(\"ref_salt\")\n\n  /// The same reference under a keyed digest, so that it can be UNIQUE.\n  ///\n  /// `refHash` cannot answer \"does this reference already exist?\" — every row\n  /// carries its own salt, so the same reference hashes differently each\n  /// time. This is one deterministic value per reference, peppered from the\n  /// environment so a stolen database still does not give the references\n  /// back. It is what the unique index below is built on; verification at the\n  /// gate still goes through `refHash`.\n  refKey String? @unique @map(\"ref_key\")\n\n  /// The temporary password an administrator hands to the customer so they\n  /// can fill the gift. Erased in the same transaction that seals it.\n  tempHash String? @map(\"temp_hash\")\n  tempSalt String? @map(\"temp_salt\")\n\n  /// Held by whoever created the pearl; required by the manage endpoints.\n  manageKey String @map(\"manage_key\")\n\n  title     String  @default(\"Pour toi\")\n  subtitle  String  @default(\"\")\n  gateTitle String  @default(\"Coquillage scellé\") @map(\"gate_title\")\n  gateNote  String  @default(\"Entrez le code secret pour révéler la perle\") @map(\"gate_note\")\n  /// The letter shown under every memory once the pearl is open.\n  message   String  @default(\"\")\n  autoplay  Boolean @default(true)\n\n  views   Int @default(0)\n  unlocks Int @default(0)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  memories Memory[]\n  sessions Session[]\n\n  @@map(\"pearls\")\n}\n\nenum PearlStatus {\n  /// Generated by an administrator, not yet filled: the gate refuses to open.\n  DRAFT\n  /// Finished by its owner. The only state the viewer will unlock.\n  SEALED\n}\n\nenum MemoryType {\n  PHOTO\n  VIDEO\n  VOICE\n  NOTE\n}\n\n/// One memory in the pile. Every kind lives here; `type` says which fields\n/// carry meaning:\n///\n///   PHOTO  title=handwritten caption · mediaUrl=full webp · thumbnailUrl\n///   VIDEO  title=label · mediaUrl=film · posterUrl=frame · duration\n///   VOICE  title=label · mediaUrl=audio · duration\n///   NOTE   title=title · date=free text (\"Été 2019\") · description=the page\nmodel Memory {\n  id      Int        @id @default(autoincrement())\n  pearlId Int        @map(\"pearl_id\")\n  type    MemoryType\n\n  /// The words on the card: a caption, a label, or the page's title.\n  title       String @default(\"\")\n  /// The body of a written memory; unused by the media kinds.\n  description String @default(\"\")\n  /// Free text, deliberately not a timestamp: the sender writes the moment\n  /// the way they would say it (\"Été 2019\", \"le soir du 12 mars\").\n  date        String @default(\"\")\n\n  /// Path of the media relative to the storage root, e.g. \"images/ab12.webp\".\n  /// Serialised to a URL by the API — the column never holds a host.\n  mediaUrl     String? @map(\"media_url\")\n  thumbnailUrl String? @map(\"thumbnail_url\")\n  posterUrl    String? @map(\"poster_url\")\n  mimeType     String? @map(\"mime_type\")\n\n  /// Seconds, for voices and films.\n  duration Float?\n  width    Int?\n  height   Int?\n\n  /// Place in the album — ONE sequence per pearl, across every type.\n  ///\n  /// It used to be numbered inside each type, and the viewer read the four\n  /// groups one after another: every photograph, then every film, then the\n  /// voices, then the written pages. That discarded the only ordering the\n  /// author ever expressed — the order they added things in. A gift built as\n  /// photo, voice, photo, note came back as photo, photo, voice, note.\n  position Int @default(0)\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  pearl Pearl @relation(fields: [pearlId], references: [id], onDelete: Cascade)\n\n  /// How the album is read back.\n  @@index([pearlId, position])\n  /// Still used: the per-kind counts, and the limit checks that guard them.\n  @@index([pearlId, type, position])\n  @@map(\"memories\")\n}\n\nenum SessionKind {\n  /// Handed out when the passcode is accepted. Lets the bearer READ the\n  /// memories of that one pearl, and nothing else.\n  VIEW\n  /// Handed out when the builder password is accepted. Lets the bearer edit\n  /// that one pearl until it expires or the gift is sealed.\n  BUILDER\n}\n\n/// The bytes of one stored file, keyed by the same storage path the Memory\n/// rows already carry (\"images/ab12.webp\"). The database is the storage, so a\n/// pearl and its photographs, films and voices are backed up, moved and\n/// deleted as one thing.\nmodel MediaBlob {\n  path      String   @id\n  mimeType  String   @map(\"mime_type\")\n  size      Int\n  data      Bytes\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@map(\"media_blobs\")\n}\n\n/// A bearer token bound to exactly one pearl, so a token minted for one gift\n/// is worth nothing against another. Sealing a gift deletes every session it\n/// had, which is what makes the temporary password stop working at once.\nmodel Session {\n  token     String      @id\n  pearlId   Int         @map(\"pearl_id\")\n  kind      SessionKind @default(BUILDER)\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  expiresAt DateTime    @map(\"expires_at\")\n\n  pearl Pearl @relation(fields: [pearlId], references: [id], onDelete: Cascade)\n\n  @@index([pearlId])\n  @@index([expiresAt])\n  @@map(\"sessions\")\n}\n\n/// One wrong guess. Counted per IP and per pearl inside a rolling window —\n/// this is what keeps a five-letter love-note of a passcode safe.\nmodel UnlockAttempt {\n  id        Int      @id @default(autoincrement())\n  slug      String\n  ip        String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  @@index([slug, ip, createdAt])\n  @@map(\"unlock_attempts\")\n}\n",
